int
samr_SAMPR_LOGON_HOURS_coder(char *name, struct dcerpc_context *dce,
                struct dcerpc_pdu *pdu,
                struct dcerpc_iovec *iov,
                void *ptr)
{
        struct samr_SAMPR_LOGON_HOURS *s = ptr;

        (void)name;
        if (dcerpc_uint16_coder("UnitsPerWeek", dce, pdu, iov, &s->UnitsPerWeek)) {
                return -1;
        }
        dcerpc_set_size_is(pdu, 1260);
        dcerpc_set_length_is(pdu, (s->UnitsPerWeek+7)/8);
        if (dcerpc_pdu_direction(pdu) == DCERPC_ENCODE &&
            s->LogonHours.data != NULL) {
                struct dcerpc_varying_bytes *vb;

                vb = dcerpc_alloc_data(pdu, sizeof(*vb));
                if (vb == NULL) {
                        return -1;
                }
                *vb = s->LogonHours;
                vb->max_count = 1260;
                if (dcerpc_ptr_coder("LogonHours", dce, pdu, iov, vb,
                                     PTR_UNIQUE, dcerpc_varying_bytes_checked_coder)) {
                        return -1;
                }
        } else {
                if (dcerpc_ptr_coder("LogonHours", dce, pdu, iov,
                                     (dcerpc_pdu_direction(pdu) == DCERPC_ENCODE) ? NULL : &s->LogonHours,
                                     PTR_UNIQUE, dcerpc_varying_bytes_checked_coder)) {
                        return -1;
                }
                /* NDR decodes the deferred bytes, and max_count, later */
                if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE) {
                        s->LogonHours.max_count = 1260;
                }
        }

        return 0;
}

