/* The union as a [switch_is] parameter: discriminant from switch_is */
int
samr_SAMPR_USER_INFO_BUFFER_switch_coder(char *name, struct dcerpc_context *dce,
                struct dcerpc_pdu *pdu,
                struct dcerpc_iovec *iov,
                void *ptr)
{
        uint32_t level = dcerpc_get_switch_is(pdu);

        return dcerpc_union_enum16_coder(name, dce, pdu, iov, &level, ptr,
                                         samr_SAMPR_USER_INFO_BUFFER_coder, 4, 8);
}

/* A unique pointer to the union: NULL encodes a NULL referent */
int
samr_SAMPR_USER_INFO_BUFFER_switch_ptr_coder(char *name, struct dcerpc_context *dce,
                struct dcerpc_pdu *pdu,
                struct dcerpc_iovec *iov,
                void *ptr)
{
        union samr_SAMPR_USER_INFO_BUFFER **pp = ptr;

        if (dcerpc_pdu_direction(pdu) == DCERPC_DECODE && *pp == NULL) {
                *pp = dcerpc_alloc_data(pdu, sizeof(**pp));
                if (*pp == NULL) {
                        return -1;
                }
        }
        return samr_SAMPR_USER_INFO_BUFFER_switch_coder(name, dce, pdu, iov, *pp);
}

